using Cosmos.API.Security;using Cosmos.Application.Abstractions.Services;using Cosmos.Application.PurchaseExpense;using Cosmos.Domain.Security;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace Cosmos.API.Controllers;
[Authorize,Tags("PurchaseReturnsController"),ApiExplorerSettings(GroupName="Purchase & Expense"),Route("api/purchase-returns")]
public sealed class PurchaseReturnsController(IPurchaseExpenseService s):ApiControllerBase { [HttpGet,RequirePermission("PurchaseExpense.PurchaseReturn",PermissionAction.View)]public async Task<IActionResult>List([FromQuery]PurchaseReturnListQuery q,CancellationToken ct)=>FromResponse(await s.GetPurchaseReturnsAsync(q,ct));[HttpGet("{id:long}"),RequirePermission("PurchaseExpense.PurchaseReturn",PermissionAction.View)]public async Task<IActionResult>Get(long id,CancellationToken ct)=>FromResponse(await s.GetPurchaseReturnAsync(id,ct));[HttpPost,RequirePermission("PurchaseExpense.PurchaseReturn",PermissionAction.Create)]public async Task<IActionResult>Create(CreatePurchaseReturnRequest r,CancellationToken ct)=>FromResponse(await s.CreatePurchaseReturnAsync(r,ct),201);[HttpPut("{id:long}"),RequirePermission("PurchaseExpense.PurchaseReturn",PermissionAction.Edit)]public async Task<IActionResult>Update(long id,UpdatePurchaseReturnRequest r,CancellationToken ct)=>FromResponse(await s.UpdatePurchaseReturnAsync(id,r,ct));[HttpDelete("{id:long}"),RequirePermission("PurchaseExpense.PurchaseReturn",PermissionAction.Delete)]public async Task<IActionResult>Delete(long id,CancellationToken ct)=>FromResponse(await s.DeletePurchaseReturnAsync(id,ct)); }
